use vstd::prelude::*;

verus! {

/// Given a non‐empty vector `a` of i8, returns the maximum element of `a`.
/// The result is one of the elements of `a`, every element of `a` is
/// ≤ the result, and among all occurrences of the maximum value, the
/// returned one occurs at the smallest index.
fn amax(a: Vec<i8>) -> (result: i8)
    requires
        // non‐empty
        a.len() > 0,
    ensures
        // there is some index k witnessing result
        exists |k: usize| k < a.len() &&
            // a[k] equals the result
            a[k] == result &&
            // k is the first occurrence of result
            (forall |l: usize| l < a.len() && a[l] == result ==> k <= l) &&
            // every element is ≤ result
            (forall |j: usize| j < a.len() ==> a[j] <= result)
{
    let len = a.len();
    // start with the 0‐th element
    let mut max_idx: usize = 0;
    let mut max_val: i8  = a[0];
    let mut i: usize     = 1;

    // scan from i = 1..len, maintaining that
    //  0 < i ≤ len,
    //  max_idx < i,
    //  a[max_idx] == max_val,
    //  for all j < i: a[j] ≤ max_val,
    //  for all l < i with a[l] == max_val, max_idx ≤ l,
    //  a.len() == len
    while i < len
        invariant
            1 <= i && i <= len,
            max_idx < i,
            a[max_idx] == max_val,
            forall |j: usize| j < i ==> a[j] <= max_val,
            forall |l: usize| l < i && a[l] == max_val ==> max_idx <= l,
            len == a.len(),
        decreases
            len - i,
    {
        if a[i] > max_val {
            max_val = a[i];
            max_idx = i;
        }
        i = i + 1;
    }

    // now i == len, so by the invariant
    //   0 ≤ max_idx < len, a[max_idx] == max_val,
    //   for all j < len, a[j] ≤ max_val,
    //   and for all l < len with a[l] == max_val, max_idx ≤ l
    // which exactly matches our post‐condition
    max_val
}

} // verus!

fn main() {
    // Example usage (outside verification):
    let v = vec![3_i8, 1, 4, 4, 2];
    let m = amax(v);
    assert!(m == 4);
}